const NAV=[{group:'ESPAÇO DE LEITURA',items:[['dashboard','Visão geral',LayoutDashboard],['books','Acervo de livros',BookOpen],['loans','Empréstimos',ArrowRightLeft],['reservations','Reservas',Bookmark]]},{group:'NOSSA COMUNIDADE',items:[['employees','Colaboradores',Users],['club','Clube & conquistas',Rocket],['suggestions','Mural de sugestões',Lightbulb]]},{group:'GESTÃO DA BIBLIOTECA',items:[['acquisitions','Aquisições',PackagePlus],['reports','Relatórios',BarChart3]]},{group:'ADMINISTRAÇÃO',items:[['admin','Central do administrador',ShieldCheck],['admin-users','Acessos & permissões',Users],['admin-migration','Migração & qualidade',RefreshCw],['admin-audit','Histórico de atividades',FileText],['admin-backups','Importação & backup',Download],['settings','Políticas & configurações',Settings]]}];
