   <nav aria-label="Menu principal">{NAV.filter(group=>admin||group.group!=='ADMINISTRAÇÃO').map(group=><div className="nav-group" key={group.group}><p>{group.group}</p>{group.items.filter(([key])=>admin||(!String(key).startsWith('admin')&&!['settings','reports','acquisitions'].includes(key as string))).map(([key,label,Icon]:any)=><button className={'nav-item '+(view===key?'active':'')} key={key} onClick={()=>go(key)}><Icon size={19}/><span>{label}</span>{key==='loans'&&overdue.length>0&&<em>{overdue.length}</em>}{key==='club'&&<span className="nav-new">NOVO</span>}</button>)}</div>)}</nav>
